import sys

MOD = 1000000007

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    h = int(data[1])
    a = list(map(int, data[2:2+n]))

    for x in a:
        if x > h:
            print(0)
            return

    # dp[j] = number of ways with j currently open segments
    dp = [0] * (n + 2)
    dp[0] = 1

    prev = h
    for i in range(n):
        cur = a[i]
        ndp = [0] * (n + 2)

        if cur == prev:
            # can close one, keep same, or open one
            for j in range(n + 1):
                v = dp[j]
                if not v:
                    continue
                # close one
                if j > 0:
                    ndp[j - 1] = (ndp[j - 1] + v * j) % MOD
                # keep same
                ndp[j] = (ndp[j] + v) % MOD
                # open one
                ndp[j + 1] = (ndp[j + 1] + v) % MOD
        elif cur == prev - 1:
            # must open one (or close and open? net +1)
            for j in range(n + 1):
                v = dp[j]
                if not v:
                    continue
                # open one
                ndp[j + 1] = (ndp[j + 1] + v) % MOD
                # close one and open one: net same, but close choice j, open forced
                if j > 0:
                    ndp[j] = (ndp[j] + v * j) % MOD
        elif cur == prev + 1:
            # must close one
            for j in range(1, n + 1):
                v = dp[j]
                if not v:
                    continue
                ndp[j - 1] = (ndp[j - 1] + v * j) % MOD
        else:
            print(0)
            return

        dp = ndp
        prev = cur

    # after last element, must close all open segments
    ans = 0
    for j in range(n + 1):
        if dp[j]:
            # close all j segments in any order: j!
            fact = 1
            for k in range(2, j + 1):
                fact = fact * k % MOD
            ans = (ans + dp[j] * fact) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()
